get_ipython().run_cell_magic('writefile', f'{STAGING}/e5_heads.py', '"""E5A: CPU head analysis of completed deterministic E4 fp32 measurements.\n\nNo tensor collection, tokenization, model inference, or fp16 input is performed.\n"""\nimport hashlib\nimport io\nimport json\nimport math\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nCOMPONENTS = [\'source_tag\', \'target_tag\', \'source_code\', \'eos\', \'unknown\',\n              \'blank\', \'punctuation_P\', \'symbol_control\', \'content\']\nMODELS = {\n    \'it2\': (\'ai4bharat/indictrans2-indic-indic-dist-320M\',\n            \'ffb7582b6d43791f1fb26b2153fc065f2e9ea575\'),\n    \'nllb\': (\'facebook/nllb-200-distilled-600M\',\n             \'f8d333a098d19b4fd9a8b18f94170487ad3f821d\'),\n    \'madlad\': (\'google/madlad400-3b-mt\',\n               \'fa184c675da0b5c9e1c8694fccd4e12e2d422094\'),\n}\n\n\ndef progress(message):\n    print(time.strftime(\'%H:%M:%S\'), message, flush=True)\n\n\ndef require(value, message):\n    if not bool(value):\n        raise ValueError(message)\n\n\ndef sha_file(path):\n    digest = hashlib.sha256()\n    with Path(path).open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef identity(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True,\n                                    separators=(\',\', \':\')).encode()).hexdigest()\n\n\ndef atomic_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(path.suffix + \'.tmp\')\n    temporary.write_text(json.dumps(value, indent=2, allow_nan=False) + \'\\n\', encoding=\'utf-8\')\n    temporary.replace(path)\n\n\ndef atomic_csv(path, frame):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(path.suffix + \'.tmp\')\n    frame.to_csv(temporary, index=False)\n    temporary.replace(path)\n\n\ndef freeze(path, value):\n    path = Path(path)\n    if path.exists():\n        require(json.loads(path.read_text()) == value,\n                f\'Frozen configuration changed: {path}. Use a new versioned output folder.\')\n    else:\n        atomic_json(path, value)\n\n\ndef reverse(pair):\n    source, target = pair.split(\'__\')\n    return target + \'__\' + source\n\n\ndef language_design(pairs, languages, role=\'both\'):\n    """Identifiable intercept and reduced, sum-to-zero language effects."""\n    columns = [np.ones(len(pairs))]\n    for side, name in [(0, \'source\'), (1, \'target\')]:\n        if role not in (name, \'both\'):\n            continue\n        labels = np.array([pair.split(\'__\')[side] for pair in pairs])\n        for language in languages[:-1]:\n            columns.append((labels == language).astype(float) -\n                           (labels == languages[-1]).astype(float))\n    return np.column_stack(columns)\n\n\ndef coefficients(coef, n_languages):\n    alpha = np.concatenate([coef[1:n_languages], -coef[1:n_languages].sum(0, keepdims=True)])\n    beta = np.concatenate([coef[n_languages:2*n_languages-1],\n                           -coef[n_languages:2*n_languages-1].sum(0, keepdims=True)])\n    return alpha, beta\n\n\ndef operators(pairs, languages):\n    dyads = [p for p in pairs if p < reverse(p)]\n    require(len(pairs) == 40 and len(set(pairs)) == 40 and len(dyads) == 20,\n            \'Expected the observed 20-dyad / 40-direction graph\')\n    require(all(reverse(p) in pairs for p in pairs), \'Missing reciprocal direction\')\n    result = {}\n    audits = []\n    for role in [\'source\', \'both\']:\n        x = language_design(pairs, languages, role)\n        require(np.linalg.matrix_rank(x) == x.shape[1], f\'Full {role} model is unidentified\')\n        held = np.zeros((len(pairs), len(pairs)))\n        for dyad in dyads:\n            test = [pairs.index(dyad), pairs.index(reverse(dyad))]\n            train = [i for i in range(len(pairs)) if i not in test]\n            rank = int(np.linalg.matrix_rank(x[train]))\n            require(rank == x.shape[1], f\'Unidentified held-dyad fit: {dyad}, {role}\')\n            held[np.ix_(test, train)] = x[test] @ np.linalg.pinv(x[train])\n            audits.append({\'dyad\': dyad, \'role\': role, \'rank\': rank,\n                           \'expected_rank\': x.shape[1], \'training_directions\': len(train)})\n        require(all(np.all(held[np.ix_([pairs.index(p), pairs.index(reverse(p))],\n                                      [pairs.index(p), pairs.index(reverse(p))])] == 0)\n                    for p in dyads), \'Held-dyad outcome leakage\')\n        result[role] = held\n    x = language_design(pairs, languages)\n    result[\'coefficient_operator\'] = np.linalg.pinv(x)\n    result[\'dyads\'] = dyads\n    return result, pd.DataFrame(audits)\n\n\ndef validate_support(frame, split):\n    ids = sorted(split[\'train\'] + split[\'validation\'] + split[\'test\'])\n    require([len(split[k]) for k in [\'train\', \'validation\', \'test\']] == [315, 67, 68],\n            \'Expected the frozen E1 315/67/68 split\')\n    require(len(set(ids)) == 450, \'Meaning leakage/duplicates in split\')\n    require(len(frame) == 18000 and not frame.duplicated([\'pair\', \'sentence_id\']).any(),\n            \'E4 panel is incomplete or duplicated; no row exclusions are allowed\')\n    require(set(frame.sentence_id) == set(ids), \'E4 meaning support changed\')\n    require(frame.groupby(\'sentence_id\').pair.nunique().eq(40).all(), \'Incomplete meaning block\')\n    require(frame.groupby(\'sentence_id\').corpus_sentence_id.nunique().eq(1).all(),\n            \'Corpus identity disagrees across directions\')\n    pairs = sorted(frame.pair.unique())\n    languages = sorted({language for pair in pairs for language in pair.split(\'__\')})\n    require(len(languages) == 11, \'Expected the same 11 languages\')\n    require(np.isfinite(frame[COMPONENTS].to_numpy(float)).all(), \'Nonfinite E4 mass\')\n    require(np.allclose(frame[COMPONENTS].sum(1), 1, atol=1e-5, rtol=0), \'E4 mean closure failed\')\n    return ids, pairs, languages\n\n\ndef read_verified_panel(e4_root, study, split, cache_root, expected_sources):\n    """Read each small Drive part once; pack verified shares into a local .npy.\n\n    Every NPZ is read with allow_pickle=False. Resume caches are tied to every\n    upstream stamp/hash, the E4 completion lock, and this loader source.\n    """\n    root = Path(e4_root) / \'collectors\' / study\n    stamp = json.loads((root / \'complete.json\').read_text())\n    lock = json.loads((root / \'run_lock.json\').read_text())\n    require(stamp[\'worker_sha256\'] == expected_sources[\'e4_worker.py\'] and\n            stamp[\'support_code_sha256\'] == expected_sources, \'E4 collector code provenance changed\')\n    require(stamp[\'all_rows_sha256\'] == sha_file(root / \'all_rows.csv\'), \'E4 CSV changed\')\n    require(stamp[\'run_lock_sha256\'] == sha_file(root / \'run_lock.json\'), \'E4 run lock changed\')\n    require(lock[\'precision\'] == \'fp32\' and lock[\'attention\'] == \'eager\' and\n            lock[\'python_hash_seed\'] == 0, \'Expected deterministic E4 v3 fp32 collector\')\n    repo, revision = MODELS[study]\n    require((lock[\'model\'][\'repo\'], lock[\'model\'][\'revision\']) == (repo, revision),\n            \'Model checkpoint changed\')\n    frame = pd.read_csv(root / \'all_rows.csv\', dtype={\'corpus_sentence_id\': str})\n    ids, pairs, languages = validate_support(frame, split)\n    require(sorted(p.name for p in (root / \'parts\').iterdir() if p.is_dir()) == pairs,\n            \'E4 part directories do not match the observed graph\')\n    catalog = []\n    for pair in pairs:\n        folder = root / \'parts\' / pair\n        require(sorted(p.name for p in folder.glob(\'*.json\')) ==\n                [f\'{start:04d}.json\' for start in range(0, 450, 25)], \'E4 part stamps are incomplete\')\n        for start in range(0, 450, 25):\n            info = json.loads((folder / f\'{start:04d}.json\').read_text())\n            require(info[\'fingerprint\'] == stamp[\'fingerprint\'], \'Mixed E4 part fingerprints\')\n            catalog.append({\'pair\': pair, \'start\': start, **info})\n        if len(catalog) == 18 or len(catalog) % 90 == 0:\n            progress(f\'{study}: checked checkpoint metadata {len(catalog)}/720\')\n    signature = {\'study\': study, \'complete_sha256\': sha_file(root / \'complete.json\'),\n                 \'source_sha256\': sha_file(__file__), \'split\': split, \'parts\': catalog}\n    cache = Path(cache_root) / study\n    cache.mkdir(parents=True, exist_ok=True)\n    data_path = cache / \'shares.npy\'\n    complete_path = cache / \'complete.json\'\n    if complete_path.is_file():\n        saved = json.loads(complete_path.read_text())\n        require(saved[\'input_identity\'] == identity(signature), \'Local panel cache belongs to different inputs\')\n        require(saved[\'npy_sha256\'] == sha_file(data_path), \'Local packed panel changed\')\n        data = np.load(data_path, mmap_mode=\'r\', allow_pickle=False)\n        progress(f\'{study}: verified local packed cache; no NPZ reread\')\n        return frame, data, ids, pairs, languages, signature\n    started = time.perf_counter()\n    temporary = data_path.with_suffix(\'.tmp.npy\')\n    packed = None\n    shape = None\n    reference = frame.set_index([\'pair\', \'sentence_id\'])\n    row_lookup = {v: i for i, v in enumerate(ids)}\n    for i, item in enumerate(catalog):\n        pair, start = item[\'pair\'], item[\'start\']\n        folder = root / \'parts\' / pair\n        csv_path = folder / f\'{start:04d}.csv\'\n        npz_path = folder / f\'{start:04d}.npz\'\n        # Load bytes once; hash and parse the same bytes to avoid a second Drive read.\n        csv_raw, npz_raw = csv_path.read_bytes(), npz_path.read_bytes()\n        require(hashlib.sha256(csv_raw).hexdigest() == item[\'csv_sha256\'] and\n                hashlib.sha256(npz_raw).hexdigest() == item[\'npz_sha256\'],\n                f\'E4 part checksum failed: {pair}/{start:04d}\')\n        rows = pd.read_csv(io.BytesIO(csv_raw), dtype={\'corpus_sentence_id\': str})\n        expected_ids = ids[start:start+25]\n        require(rows.sentence_id.tolist() == expected_ids and rows.pair.eq(pair).all(),\n                \'Part order/meaning identity changed\')\n        original = reference.loc[[(pair, sid) for sid in expected_ids]].reset_index()\n        require(rows.corpus_sentence_id.tolist() == original.corpus_sentence_id.tolist(),\n                \'Part corpus IDs disagree with final panel\')\n        require(np.allclose(rows[COMPONENTS], original[COMPONENTS], atol=1e-12, rtol=0),\n                \'Part masses disagree with final panel\')\n        with np.load(io.BytesIO(npz_raw), allow_pickle=False) as z:\n            require(z[\'columns\'].tolist() == COMPONENTS, \'Head component order changed\')\n            require(z[\'sentence_id\'].tolist() == expected_ids, \'NPZ meaning IDs disagree with CSV\')\n            shares = z[\'shares\']\n        require(shares.dtype == np.float32 and shares.ndim == 4 and shares.shape[0] == len(expected_ids)\n                and shares.shape[-1] == 9, \'Expected fp32 meaning × layer × head × component shares\')\n        require(np.isfinite(shares).all() and shares.min() >= -1e-7 and\n                np.max(np.abs(shares.sum(-1)-1)) < 1e-5, \'Per-head closure/nonfinite failure\')\n        require(np.allclose(shares.mean((1, 2)), rows[COMPONENTS].to_numpy(), atol=1e-6, rtol=0),\n                \'Saved per-head averages do not reproduce same-forward E4 CSV\')\n        if packed is None:\n            shape = shares.shape[1:3]\n            packed = np.lib.format.open_memmap(temporary, mode=\'w+\', dtype=np.float32,\n                                               shape=(450, 40, *shape, 9))\n        require(shares.shape[1:3] == shape, \'Head/layer dimensions changed within model\')\n        packed[[row_lookup[sid] for sid in expected_ids], pairs.index(pair)] = shares\n        if i == 0 or (i+1) % 40 == 0 or i+1 == len(catalog):\n            progress(f\'{study}: verified head parts {i+1}/{len(catalog)}; \'\n                     f\'{time.perf_counter()-started:.1f}s; {shape[0]} layers × {shape[1]} heads\')\n    packed.flush()\n    del packed\n    temporary.replace(data_path)\n    atomic_json(complete_path, {\'input_identity\': identity(signature), \'npy_sha256\': sha_file(data_path),\n                               \'shape\': [450, 40, *shape, 9]})\n    return frame, np.load(data_path, mmap_mode=\'r\', allow_pickle=False), ids, pairs, languages, signature\n\n\ndef raw_lexical(panel, study):\n    result = np.asarray(panel[..., COMPONENTS.index(\'content\')], dtype=float)\n    if study == \'nllb\':\n        result = result + panel[..., COMPONENTS.index(\'unknown\')]\n    return result.reshape(result.shape[0], result.shape[1], -1)\n\n\ndef prediction_metrics(y, prediction, source_prediction, weights):\n    """Fixed training fits; weights resample whole test meanings, all directions/heads jointly."""\n    # y: meaning × direction × head; weights: bootstrap × meaning.\n    weights = weights / weights.sum(1, keepdims=True)\n    m, d, h = y.shape\n    means = (weights @ y.reshape(m, -1)).reshape(len(weights), d, h)\n    second = (weights @ np.mean(y*y, axis=1))\n    mse = second - 2*np.mean(means*prediction[None], axis=1) + np.mean(prediction**2, axis=0)\n    smse = second - 2*np.mean(means*source_prediction[None], axis=1) + np.mean(source_prediction**2, axis=0)\n    variance = second - means.mean(1)**2\n    dmse = np.mean((means-prediction[None])**2, axis=1)\n    dsmse = np.mean((means-source_prediction[None])**2, axis=1)\n    dvariance = np.mean((means-means.mean(1, keepdims=True))**2, axis=1)\n    mae_by_meaning = np.mean(np.abs(y-prediction[None]), axis=1)\n    mae = weights @ mae_by_meaning\n    row_r2 = 1-np.divide(mse, variance, out=np.full_like(mse, np.nan), where=variance > 1e-15)\n    dir_r2 = 1-np.divide(dmse, dvariance, out=np.full_like(dmse, np.nan), where=dvariance > 1e-15)\n    return np.stack([row_r2, dir_r2, mae, np.sqrt(np.maximum(mse, 0)),\n                     smse-mse, dsmse-dmse], axis=-1)\n\n\nMETRIC_NAMES = [\'row_R2\', \'direction_R2\', \'row_MAE\', \'row_RMSE\',\n                \'row_MSE_gain_vs_source\', \'direction_MSE_gain_vs_source\']\n\n\ndef intervals(draws):\n    # Avoid silently turning an undefined zero-energy head into R2=0.\n    low = np.full(draws.shape[1:], np.nan)\n    high = low.copy()\n    for index in np.ndindex(low.shape):\n        values = draws[(slice(None), *index)]\n        finite = values[np.isfinite(values)]\n        if len(finite):\n            low[index], high[index] = np.quantile(finite, [.025, .975])\n    return low, high, np.isfinite(draws).sum(0)\n\n\ndef field_fractions(mean, pairs, languages):\n    dyads = [p for p in pairs if p < reverse(p)]\n    incidence = np.zeros((len(dyads), len(languages)))\n    for i, pair in enumerate(dyads):\n        a, b = pair.split(\'__\')\n        incidence[i, languages.index(a)] = 1\n        incidence[i, languages.index(b)] = -1\n    require(np.linalg.matrix_rank(incidence) == len(languages)-1, \'Language graph is disconnected\')\n    d = np.stack([mean[pairs.index(p)]-mean[pairs.index(reverse(p))] for p in dyads])\n    gradient = incidence @ np.linalg.pinv(incidence) @ d\n    total = np.sum(d*d, axis=0)\n    return np.divide(np.sum(gradient*gradient, axis=0), total,\n                     out=np.full(total.shape, np.nan), where=total > 1e-15)\n\n\ndef analyze_heads(study, panel, ids, pairs, languages, split, output, config):\n    """Train-only head selection, validation ranking, untouched-by-selection test evaluation."""\n    output = Path(output)\n    output.mkdir(parents=True, exist_ok=True)\n    ops, audits = operators(pairs, languages)\n    atomic_csv(output/\'graph_identifiability.csv\', audits)\n    n_layers, n_heads = panel.shape[2:4]\n    h = n_layers*n_heads\n    n_lang = len(languages)\n    index = {sid: i for i, sid in enumerate(ids)}\n    train_i = [index[sid] for sid in split[\'train\']]\n    val_i = [index[sid] for sid in split[\'validation\']]\n    test_i = [index[sid] for sid in split[\'test\']]\n    y = raw_lexical(panel, study)\n    train = y[train_i]\n    val, test = y[val_i], y[test_i]\n    mean = train.mean(0)\n    coef_op = ops[\'coefficient_operator\']\n    coef = coef_op @ mean\n    alpha, beta = coefficients(coef, n_lang)\n    beta_rms = np.sqrt(np.mean(beta*beta, axis=0))\n    predictions = ops[\'both\'] @ mean\n    source_predictions = ops[\'source\'] @ mean\n    vp = prediction_metrics(val, predictions, source_predictions, np.ones((1, len(val))))[0]\n    point = prediction_metrics(test, predictions, source_predictions, np.ones((1, len(test))))[0]\n    dyad_rows = []\n    for dyad in ops[\'dyads\']:\n        directions = [pairs.index(dyad), pairs.index(reverse(dyad))]\n        truth = test[:, directions]\n        prediction = predictions[directions]\n        base_prediction = source_predictions[directions]\n        error = truth-prediction[None]\n        gain = np.mean((truth-base_prediction[None])**2-error**2, axis=(0, 1))\n        for head in range(h):\n            dyad_rows.append({\'study\': study, \'dyad\': dyad, \'flat_head\': head,\n                              \'MAE\': float(np.abs(error[..., head]).mean()),\n                              \'RMSE\': float(np.sqrt(np.mean(error[..., head]**2))),\n                              \'row_MSE_gain_vs_source\': float(gain[head])})\n    head_rows = []\n    all_components = np.asarray(panel[train_i].mean((0, 1), dtype=np.float64), float).reshape(h, 9)\n    field = field_fractions(mean, pairs, languages)\n    for head in range(h):\n        head_rows.append({\'study\': study, \'flat_head\': head, \'layer\': head//n_heads,\n                          \'head\': head % n_heads, \'train_beta_RMS\': beta_rms[head],\n                          \'train_mean_raw_LM\': float(mean[:, head].mean()),\n                          \'train_gradient_fraction\': field[head],\n                          \'validation_direction_MSE_gain_vs_source\': vp[head, 5],\n                          **{\'train_mean_\'+name: all_components[head, j]\n                             for j, name in enumerate(COMPONENTS)}})\n    table = pd.DataFrame(head_rows)\n    for name, column in [(\'target_effect\', \'train_beta_RMS\'), (\'eos_mass\', \'train_mean_eos\'),\n                         (\'validation_gain\', \'validation_direction_MSE_gain_vs_source\')]:\n        table[\'rank_\'+name] = table[column].rank(ascending=False, method=\'min\').astype(int)\n\n    selected, head_sets = select_sets(table, n_layers, n_heads, config)\n    # Freeze selection before any test bootstrap or per-head test result table is written.\n    selection = {\'study\': study, \'model\': {\'repo\': MODELS[study][0], \'revision\': MODELS[study][1]},\n                 \'layer_count\': n_layers, \'heads_per_layer\': n_heads,\n                 \'indexing\': \'zero-based decoder layer and cross-attention head; flat=layer*heads_per_layer+head\',\n                 \'selection_metric\': \'train315 beta RMS, source+target OLS\',\n                 \'selection_scope\': \'training meanings only; validation/test not used for selected head sets\',\n                 \'selection_direction_scope\': \'all 40 observed training directions; future selected-head \'\n                                              \'ablation is meaning-held-out, not a test of unseen-dyad head selection\',\n                 \'split\': split, \'top_fraction\': config[\'top_fraction\'],\n                 \'per_layer_cap\': n_heads//2, \'sets\': head_sets,\n                 \'random_control_policy\': \'3 distinct sets; same count per layer; exclude selected heads; \'\n                                          \'random sets may overlap each other\',\n                 \'seed\': config[\'selection_seed\'],\n                 \'ablation_status\': \'NOT RUN: this CPU notebook only freezes head indices; no behavioral/causal conclusion\'}\n    freeze(output/\'ablation_head_sets.json\', selection)\n    atomic_csv(output/\'per_head_held_dyad_errors.csv\', pd.DataFrame(dyad_rows))\n    table[\'selected_for_primary_ablation\'] = table.flat_head.isin(selected)\n    progress(f\'{study}: froze {len(selected)}/{h} train-selected heads and 3 layer-matched controls\')\n\n    # Meanings are the independent clusters. These are conditional-on-graph tests,\n    # not tests about a population of 11 languages or about functional importance.\n    per_meaning_coef = (train.transpose(0, 2, 1).reshape(-1, 40) @ coef_op.T)\n    per_meaning_coef = per_meaning_coef.reshape(len(train), h, -1).transpose(0, 2, 1)\n    _, meaning_beta = coefficients(per_meaning_coef.transpose(1, 0, 2), n_lang)\n    meaning_beta = meaning_beta.transpose(1, 0, 2)\n    centered = (meaning_beta-beta[None]) * np.sqrt(len(train)/(len(train)-1))\n    b = config[\'n_boot\']\n    beta_draws = np.empty((b, h), dtype=np.float32)\n    eos_draws = np.empty((b, h), dtype=np.float32)\n    test_draws = np.empty((b, h, len(METRIC_NAMES)), dtype=np.float32)\n    eos_meaning = np.asarray(panel[train_i, ..., COMPONENTS.index(\'eos\')].mean(1, dtype=np.float64), float).reshape(len(train), h)\n    counts = np.zeros(h, dtype=np.int64)\n    train_rng = np.random.default_rng(config[\'bootstrap_seed\'])\n    test_rng = np.random.default_rng(config[\'bootstrap_seed\']+1)\n    null_rng = np.random.default_rng(config[\'bootstrap_seed\']+2)\n    for start in range(0, b, config[\'bootstrap_chunk\']):\n        count = min(config[\'bootstrap_chunk\'], b-start)\n        w = train_rng.multinomial(len(train), np.full(len(train), 1/len(train)), size=count)\n        sampled = (w @ meaning_beta.reshape(len(train), -1) / len(train)).reshape(count, n_lang, h)\n        beta_draws[start:start+count] = np.sqrt(np.mean(sampled*sampled, axis=1))\n        eos_draws[start:start+count] = w @ eos_meaning / len(train)\n        # Centered Rademacher cluster-multiplier null for H0: all target beta=0,\n        # conditional on the observed language graph and meanings-as-clusters.\n        signs = null_rng.integers(0, 2, size=(count, len(train)))*2-1\n        null_beta = (signs @ centered.reshape(len(train), -1)/len(train)).reshape(count, n_lang, h)\n        null_rms = np.sqrt(np.mean(null_beta*null_beta, axis=1))\n        counts += np.sum(null_rms >= beta_rms[None]-1e-15, axis=0)\n        wt = test_rng.multinomial(len(test), np.full(len(test), 1/len(test)), size=count)\n        test_draws[start:start+count] = prediction_metrics(test, predictions, source_predictions, wt)\n        if start == 0 or (start+count) % 1024 == 0 or start+count == b:\n            progress(f\'{study}: joint meaning bootstrap / cluster null {start+count:,}/{b:,}; {h} heads\')\n    table[\'target_effect_p_cluster_multiplier\'] = (counts+1)/(b+1)\n    table[\'target_effect_beta_RMS_ci_low\'], table[\'target_effect_beta_RMS_ci_high\'] = np.quantile(beta_draws, [.025, .975], axis=0)\n    table[\'train_mean_eos_ci_low\'], table[\'train_mean_eos_ci_high\'] = np.quantile(eos_draws, [.025, .975], axis=0)\n    low, high, valid = intervals(test_draws)\n    for j, name in enumerate(METRIC_NAMES):\n        table[\'test_\'+name] = point[:, j]\n        table[\'test_\'+name+\'_ci_low\'] = low[:, j]\n        table[\'test_\'+name+\'_ci_high\'] = high[:, j]\n        table[\'test_\'+name+\'_valid_bootstraps\'] = valid[:, j]\n    atomic_csv(output/\'per_head_results.csv\', table)\n    coefficient_rows = []\n    for head in range(h):\n        for j, language in enumerate(languages):\n            coefficient_rows.append({\'study\': study, \'flat_head\': head, \'layer\': head//n_heads,\n                                     \'head\': head % n_heads, \'language\': language,\n                                     \'alpha\': alpha[j, head], \'beta\': beta[j, head],\n                                     \'theta_alpha_minus_beta\': alpha[j, head]-beta[j, head]})\n    atomic_csv(output/\'per_head_language_coefficients.csv\', pd.DataFrame(coefficient_rows))\n    atomic_csv(output/\'layer_summary.csv\', table.groupby(\'layer\', as_index=False).agg(\n        head_count=(\'head\', \'size\'), mean_beta_RMS=(\'train_beta_RMS\', \'mean\'),\n        mean_lexical_mass=(\'train_mean_raw_LM\', \'mean\'),\n        mean_EOS=(\'train_mean_eos\', \'mean\'), mean_blank=(\'train_mean_blank\', \'mean\'),\n        mean_test_direction_R2=(\'test_direction_R2\', \'mean\'),\n        mean_test_direction_MSE_gain_vs_source=(\'test_direction_MSE_gain_vs_source\', \'mean\'),\n        selected_heads=(\'selected_for_primary_ablation\', \'sum\')))\n    concentration = concentration_rows(table)\n    atomic_csv(output/\'head_signal_concentration.csv\', concentration)\n    averaged = prediction_metrics(test.mean(-1, keepdims=True), predictions.mean(-1, keepdims=True),\n                                 source_predictions.mean(-1, keepdims=True),\n                                 np.ones((1, len(test))))[0, 0]\n    atomic_csv(output/\'aggregate_head_average_prediction.csv\', pd.DataFrame([\n        {\'study\': study, \'metric\': name, \'estimate\': float(value)}\n        for name, value in zip(METRIC_NAMES, averaged)]))\n    return table, selection, concentration\n\n\ndef select_sets(table, n_layers, n_heads, config):\n    """Cap prevents an entire layer being selected, so disjoint layer-matched controls exist."""\n    k = max(1, math.ceil(config[\'top_fraction\']*len(table)))\n    cap = n_heads//2\n    require(cap >= 1 and k <= n_layers*cap, \'Top-fraction/layer-cap combination is infeasible\')\n    ranked = table.sort_values([\'train_beta_RMS\', \'flat_head\'], ascending=[False, True])\n    selected = []\n    per_layer = np.zeros(n_layers, int)\n    for row in ranked.itertuples(index=False):\n        if per_layer[row.layer] >= cap:\n            continue\n        selected.append(int(row.flat_head))\n        per_layer[row.layer] += 1\n        if len(selected) == k:\n            break\n    require(len(selected) == k, \'Unable to form the predeclared selected set\')\n    rng = np.random.default_rng(config[\'selection_seed\'])\n    controls = []\n    for _ in range(1000):\n        candidate = []\n        for layer, count in enumerate(per_layer):\n            pool = [layer*n_heads+j for j in range(n_heads) if layer*n_heads+j not in selected]\n            candidate.extend(map(int, rng.choice(pool, size=int(count), replace=False)))\n        candidate.sort()\n        if candidate not in controls:\n            controls.append(candidate)\n        if len(controls) == 3:\n            break\n    require(len(controls) == 3, \'Cannot make 3 distinct matched controls; stop, do not silently change the design\')\n    def entries(values):\n        return [{\'layer\': i//n_heads, \'head\': i % n_heads, \'flat_head\': i} for i in sorted(values)]\n    return selected, {\'baseline\': [], \'top_target_effect\': entries(selected),\n                      **{f\'random_{i+1}\': entries(value) for i, value in enumerate(controls)}}\n\n\ndef gini(values):\n    values = np.sort(np.maximum(np.asarray(values, float), 0))\n    if values.sum() <= 0:\n        return np.nan\n    return float((2*np.dot(np.arange(1, len(values)+1), values)/(len(values)*values.sum())) -\n                 (len(values)+1)/len(values))\n\n\ndef concentration_rows(table):\n    result = []\n    for label, values in [(\'squared_beta_RMS\', table.train_beta_RMS.to_numpy()**2),\n                          (\'EOS_mass\', table.train_mean_eos.to_numpy()),\n                          (\'positive_validation_prediction_gain\', np.maximum(\n                              table.validation_direction_MSE_gain_vs_source.to_numpy(), 0))]:\n        ordered = np.sort(values)[::-1]\n        for fraction in [.05, .10, .20]:\n            k = max(1, math.ceil(len(values)*fraction))\n            result.append({\'study\': table.study.iloc[0], \'signal\': label, \'top_fraction\': fraction,\n                           \'head_count\': k, \'signal_share\': ordered[:k].sum()/ordered.sum()\n                           if ordered.sum() > 0 else np.nan, \'gini\': gini(values),\n                           \'interpretation\': \'sum of nonnegative per-head strengths, not additive \'\n                           \'contributions to aggregate field energy or causal behavioral importance\'})\n    return pd.DataFrame(result)\n\n\ndef multiplicity(table):\n    """One primary family across all model/head tests; BY allows arbitrary dependence."""\n    table = table.copy()\n    p = table.target_effect_p_cluster_multiplier.to_numpy(float)\n    require(np.isfinite(p).all() and ((p > 0) & (p <= 1)).all(), \'Invalid head p-values\')\n    order = np.argsort(p, kind=\'stable\')\n    m = len(p)\n    adjusted = np.minimum.accumulate((p[order]*m/np.arange(1, m+1))[::-1])[::-1]\n    bh = np.empty(m)\n    bh[order] = np.minimum(adjusted, 1)\n    table[\'q_BH_secondary\'] = bh\n    table[\'q_BY_primary\'] = np.minimum(bh*np.sum(1/np.arange(1, m+1)), 1)\n    table[\'target_effect_BY_q_le_005\'] = table.q_BY_primary <= .05\n    return table\n\n\ndef verify_same_support(frames):\n    reference = frames[0][[\'pair\', \'sentence_id\', \'corpus_sentence_id\']].sort_values([\'pair\', \'sentence_id\']).reset_index(drop=True)\n    for frame in frames[1:]:\n        value = frame[[\'pair\', \'sentence_id\', \'corpus_sentence_id\']].sort_values([\'pair\', \'sentence_id\']).reset_index(drop=True)\n        require(reference.equals(value), \'Cross-model meaning/direction support differs; no intersection or imputation\')\n\n\ndef make_figures(table, output):\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    output = Path(output)\n    studies = list(MODELS)\n    fig, axes = plt.subplots(3, 5, figsize=(19, 11), constrained_layout=True)\n    plots = [(\'train_beta_RMS\', \'Training target-effect RMS\', \'viridis\'),\n             (\'train_mean_raw_LM\', \'Training lexical mass\', \'viridis\'),\n             (\'train_mean_eos\', \'Training EOS mass\', \'magma\'),\n             (\'train_mean_blank\', \'Training blank/separator mass\', \'magma\'),\n             (\'test_direction_MSE_gain_vs_source\', \'Test gain vs source-only\', \'coolwarm\')]\n    for row, study in enumerate(studies):\n        subset = table[table.study == study]\n        for col, (name, title, cmap) in enumerate(plots):\n            matrix = subset.pivot(index=\'layer\', columns=\'head\', values=name)\n            options = {}\n            if col == 4:\n                limit = max(float(np.abs(matrix.to_numpy()).max()), 1e-12)\n                options = {\'vmin\': -limit, \'vmax\': limit}\n            im = axes[row, col].imshow(matrix, aspect=\'auto\', origin=\'lower\', cmap=cmap, **options)\n            axes[row, col].set_title(title, fontsize=10)\n            axes[row, col].set_xlabel(\'Head (zero-based)\', fontsize=9)\n            axes[row, col].set_ylabel(study.upper()+\'\\nDecoder layer (zero-based)\', fontsize=9)\n            axes[row, col].set_xticks(np.arange(0, len(matrix.columns), max(1, len(matrix.columns)//8)))\n            axes[row, col].set_yticks(np.arange(0, len(matrix.index), max(1, len(matrix.index)//8)))\n            fig.colorbar(im, ax=axes[row, col], shrink=.8)\n    for suffix in [\'png\', \'pdf\']:\n        fig.savefig(output/(\'E5_layer_head_maps.\'+suffix), dpi=180)\n    plt.close(fig)\n    fig, axes = plt.subplots(1, 3, figsize=(14, 4), constrained_layout=True)\n    for ax, (column, name) in zip(axes, [(\'train_beta_RMS\', \'Squared target-effect RMS\'),\n                                       (\'train_mean_eos\', \'EOS mass\'),\n                                       (\'validation_direction_MSE_gain_vs_source\', \'Positive validation prediction gain\')]):\n        for study in studies:\n            values = table.loc[table.study == study, column].to_numpy()\n            values = values**2 if column == \'train_beta_RMS\' else np.maximum(values, 0)\n            if values.sum() <= 0:\n                continue\n            y = np.r_[0, np.cumsum(np.sort(values)[::-1])/values.sum()]\n            ax.plot(np.linspace(0, 1, len(y)), y, label=study.upper())\n        ax.plot([0, 1], [0, 1], \'--\', color=\'grey\', linewidth=.7)\n        ax.set(title=name, xlabel=\'Fraction of heads, ranked by this quantity\',\n               ylabel=\'Fraction of summed per-head strength\', xlim=(0, 1), ylim=(0, 1))\n        ax.legend()\n    for suffix in [\'png\', \'pdf\']:\n        fig.savefig(output/(\'E5_head_concentration.\'+suffix), dpi=180)\n    plt.close(fig)\n\n\ndef run(config):\n    import importlib.metadata\n    import zipfile\n    output = Path(config[\'output\'])\n    output.mkdir(parents=True, exist_ok=True)\n    root = Path(config[\'e4_root\'])\n    require(sha_file(__file__) == config[\'source_sha256\'], \'E5 source changed after configuration freeze\')\n    split = json.loads((root/\'meaning_split.json\').read_text())\n    require(identity(split) == config[\'expected_split_identity\'], \'Frozen E1 split changed\')\n    sources = json.loads((root/\'source_identity.json\').read_text())\n    require(sources == config[\'expected_e4_sources\'], \'This is not the audited deterministic E4 v3 code\')\n    signature = {**config, \'packages\': {name: importlib.metadata.version(name)\n                                      for name in [\'numpy\', \'pandas\', \'matplotlib\']},\n                 \'e4_complete_sha256\': {study: sha_file(root/\'collectors\'/study/\'complete.json\')\n                                       for study in MODELS}}\n    freeze(output/\'run_lock.json\', signature)\n    freeze(output/\'protocol.json\', config[\'protocol\'])\n    freeze(output/\'meaning_split.json\', split)\n    (output/\'e5_heads.py\').write_bytes(Path(__file__).read_bytes())\n    tables, frames, concentrations, selections = [], [], [], {}\n    for study in MODELS:\n        folder = output/study\n        done = folder/\'complete.json\'\n        model_identity = identity({\'lock\': signature, \'study\': study})\n        if done.is_file():\n            saved = json.loads(done.read_text())\n            require(saved[\'identity\'] == model_identity, \'Completed model belongs to different E5 settings\')\n            for name, digest in saved[\'files\'].items():\n                require(sha_file(folder/name) == digest, f\'Changed E5 result: {study}/{name}\')\n            frame = pd.read_csv(root/\'collectors\'/study/\'all_rows.csv\', dtype={\'corpus_sentence_id\': str})\n            upstream = json.loads((root/\'collectors\'/study/\'complete.json\').read_text())\n            require(sha_file(root/\'collectors\'/study/\'all_rows.csv\') == upstream[\'all_rows_sha256\'],\n                    \'Upstream E4 CSV changed\')\n            table = pd.read_csv(folder/\'per_head_results.csv\')\n            selection = json.loads((folder/\'ablation_head_sets.json\').read_text())\n            concentration = pd.read_csv(folder/\'head_signal_concentration.csv\')\n            progress(study+\': verified complete E5 head analysis; skipping recomputation\')\n        else:\n            progress(\'=== E5A \'+study.upper()+\' ===\')\n            frame, data, ids, pairs, languages, upstream = read_verified_panel(\n                root, study, split, config[\'cache\'], sources)\n            freeze(folder/\'input_audit.json\', upstream)\n            raw = raw_lexical(data, study).mean(-1)\n            reference = frame.pivot(index=\'sentence_id\', columns=\'pair\', values=\'raw_lm\').loc[ids, pairs].to_numpy()\n            max_delta = float(np.max(np.abs(raw-reference)))\n            require(max_delta <= 1e-6, \'Head average does not reproduce E4 raw LM\')\n            atomic_json(folder/\'aggregate_reproduction.json\', {\'max_absolute_LM_delta\': max_delta,\n                                                              \'rows\': 18000, \'head_shape\': list(data.shape[2:4])})\n            table, selection, concentration = analyze_heads(study, data, ids, pairs, languages, split,\n                                                            folder, config)\n            # Linear head averaging must also reproduce E4\'s held-dyad S0 fit.\n            e4_metrics = pd.read_csv(root/\'analysis\'/study/\'test_metrics_with_CI.csv\')\n            reproduced = pd.read_csv(folder/\'aggregate_head_average_prediction.csv\').set_index(\'metric\').estimate\n            for scale, name in [(\'individual_rows\', \'row_R2\'), (\'direction_means\', \'direction_R2\')]:\n                old = e4_metrics[(e4_metrics.outcome == \'raw_lm\') &\n                                 (e4_metrics.specification == \'S0_language\') &\n                                 (e4_metrics.scale == scale) & (e4_metrics.metric == \'R2_test_centered\')]\n                require(len(old) == 1 and abs(float(old.estimate.iloc[0])-reproduced[name]) <= 1e-5,\n                        \'Aggregated E5 head predictions disagree with E4 S0\')\n            names = sorted(p.name for p in folder.iterdir() if p.is_file() and p.name != \'complete.json\')\n            atomic_json(done, {\'identity\': model_identity, \'files\': {name: sha_file(folder/name) for name in names}})\n            del data, raw, reference\n        frames.append(frame)\n        tables.append(table)\n        concentrations.append(concentration)\n        selections[study] = selection\n    verify_same_support(frames)\n    combined = multiplicity(pd.concat(tables, ignore_index=True))\n    atomic_csv(output/\'E5_per_head_results.csv\', combined)\n    atomic_csv(output/\'E5_signal_concentration.csv\', pd.concat(concentrations, ignore_index=True))\n    atomic_json(output/\'E5_ablation_head_sets.json\', selections)\n    summaries = []\n    for study in MODELS:\n        q = combined[combined.study == study]\n        summaries.append({\'study\': study, \'layers\': int(q.layer.max()+1),\n                          \'heads_per_layer\': int(q[\'head\'].max()+1), \'total_heads\': len(q),\n                          \'target_effect_BY_discoveries\': int(q.target_effect_BY_q_le_005.sum()),\n                          \'positive_test_gain_heads\': int((q.test_direction_MSE_gain_vs_source > 0).sum()),\n                          \'median_test_direction_R2\': float(q.test_direction_R2.median()),\n                          \'selected_head_count\': int(q.selected_for_primary_ablation.sum()),\n                          \'behavioral_ablation_completed\': False})\n    summary = pd.DataFrame(summaries)\n    atomic_csv(output/\'E5_head_summary.csv\', summary)\n    make_figures(combined, output)\n    atomic_json(output/\'status.json\', {\'experiment\': \'E5A\', \'CPU_head_analysis_complete\': True,\n                                     \'GPU_ablation_complete\': False, \'quality_evaluation_complete\': False,\n                                     \'scope\': \'E5 is not complete until selected versus matched-random head \'\n                                     \'ablation and paired behavioral quality evaluation are run.\'})\n    # No source text, generated text, input token IDs, or packed head tensors in this release.\n    files = sorted(p for p in output.rglob(\'*\') if p.is_file() and p.name != \'completed_all.json\'\n                   and p.suffix not in {\'.tmp\', \'.zip\'} and \'private_logs\' not in p.parts)\n    atomic_json(output/\'completed_all.json\', {\'stage\': \'E5A\', \'ablation_not_run\': True,\n                                            \'files\': {str(p.relative_to(output)): sha_file(p) for p in files}})\n    archive = output.with_name(output.name+\'_results.zip\')\n    temporary = archive.with_suffix(\'.tmp.zip\')\n    with zipfile.ZipFile(temporary, \'w\', compression=zipfile.ZIP_DEFLATED) as bundle:\n        for path in files+[output/\'completed_all.json\']:\n            bundle.write(path, str(path.relative_to(output)))\n    temporary.replace(archive)\n    progress(\'E5A complete. Results: \'+str(output))\n    print(summary.to_string(index=False), flush=True)\n    print(\'GPU ablation has NOT been run. Head-effect tests are descriptive, not evidence of causal importance.\', flush=True)\n\n\nif __name__ == \'__main__\':\n    import argparse\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n\n')


